gdr.ValidationScript:
// eslint-disable-next-line @typescript-eslint/no-unused-vars
var ValidationScript;
(function (ValidationScript) {
    var NamedLog = Lib.P2P.Logger.NamedLog;
    class Main {
        constructor() {
            this.logger = new NamedLog({ namespace: "Bulk Receipt" });
        }
        ActionSubmit(asynchrone) {
            this.logger.Info("ActionSubmit");
            if (Lib.P2P.FormHasError()) {
                throw "Form is in error";
            }
            Lib.Purchasing.SetRightForP2PSupervisor();
            Lib.Purchasing.SetRightForProcurementViewer();
            Lib.Purchasing.SetRightToCustomUsers("BR");
            Lib.Purchasing.Receiving.InitBulkReceiptNumber();
            const brToGr = new Lib.Purchasing.Receiving.BRToGR();
            const lineItems = Data.GetTable("LineItems__");
            let itemCount = lineItems.GetItemCount();
            let lineIdx = 0;
            while (lineIdx < itemCount) {
                const item = lineItems.GetItem(lineIdx);
                if (Lib.Purchasing.Receiving.IsItemToReceive(item, brToGr)) {
                    lineIdx++;
                }
                else {
                    Log.Info(`Removing line item #${lineIdx} because it has no reception`);
                    itemCount = item.RemoveItem();
                }
            }
            const counts = Lib.Purchasing.Receiving.CreateMultipleGRsPerPO(Sys.Helpers.Data.GetTableAsArray("LineItems__"), brToGr, Lib.P2P.GetValidatorOrOwnerLogin());
            this.logger.Info(`Total Goods receipt to create: ${counts.total}, created: ${counts.created}`);
            if (counts.created === counts.total) {
                Data.SetValue("BRStatus__", "Success");
            }
            else {
                Data.SetValue("BRStatus__", counts.created === 0 ? "Error" : "Partial success");
                if (asynchrone) {
                    Lib.Purchasing.BR.SendEmailNotification("Purchasing_Email_NotifBRError.htm");
                }
                else {
                    // NextAlert
                }
            }
        }
        Start() {
            // Index LineItems table to ES for better reporting
            Lib.P2P.SetTablesToIndex(["LineItems__"]);
            const actionName = Data.GetActionName();
            const actionType = Data.GetActionType();
            Log.Info(`ActionName: "${actionName}" ActionType: "${actionType}"`);
            // @ts-ignore
            Data.SetRequired("DeliveryDate__", false);
            if (actionName === "" && actionType === "") {
                if (Data.GetValue("State") === 50) {
                    if (Sys.Helpers.Data.IsTrue(Variable.GetValueAsString("SubmittedFromMobileApp")) || Sys.Helpers.Data.IsTrue(Variable.GetValueAsString("SubmittedFromAgent"))) {
                        this.ActionSubmit(true);
                    }
                    else {
                        Process.PreventApproval();
                    }
                }
            }
            else {
                switch (actionName) {
                    case "Approve":
                        this.ActionSubmit(actionType === "approve_asynchronous");
                        break;
                    default:
                        Log.Warn("Unknown action");
                        Process.PreventApproval();
                        break;
                }
            }
            Sys.Helpers.TryCallFunction("Lib.BR.Customization.Server.OnValidationScriptEnd");
        }
    }
    ValidationScript.Main = Main;
    if (typeof _ENV_TEST_ENABLED === "undefined") {
        const main = new Main();
        main.Start();
    }
})(ValidationScript || (ValidationScript = {}));
//# sourceMappingURL=validationscript.js.map

gdr.ExtractionScript:
var ExtractionScript;
(function (ExtractionScript) {
    var NamedLog = Lib.P2P.Logger.NamedLog;
    class Main {
        constructor() {
            this.logger = new NamedLog({ namespace: "Bulk Receipt" });
        }
        async Start() {
            const actionName = Data.GetActionName();
            const actionType = Data.GetActionType();
            Log.Info(`-- BR Extraction Script -- Name: '${actionName || "<empty>"}', Action: '${actionType || "<empty>"}'`);
            const bulkReceiptDataStr = Variable.GetValueAsString("BulkReceiptData");
            if ((actionName === "" && actionType === "") && (bulkReceiptDataStr !== "")) {
                const bulkReceiptDataHandler = new BulkReceiptDataHandler();
                await bulkReceiptDataHandler.Load(bulkReceiptDataStr);
            }
        }
    }
    ExtractionScript.Main = Main;
    class BulkReceiptDataHandler {
        constructor() {
            this.logger = new NamedLog({ namespace: "BulkReceiptDataHandler" });
        }
        async Load(bulkReceiptDataStr) {
            const bulkReceiptData = this.ParseBulkReceiptData(bulkReceiptDataStr);
            if (bulkReceiptData) {
                await this.LoadBulkReceiptData(bulkReceiptData);
            }
        }
        ParseBulkReceiptData(bulkReceiptDataStr) {
            try {
                return JSON.parse(bulkReceiptDataStr);
            }
            catch (e) {
                this.logger.Error(`Error parsing BulkReceiptData: ${e}`);
            }
        }
        async LoadBulkReceiptData(bulkReceiptData) {
            const items = bulkReceiptData.Items;
            if (!items) {
                this.logger.Error("No items in BulkReceiptData");
                return false;
            }
            // delivery date
            if (bulkReceiptData.DeliveryDate) {
                Data.SetValue("DeliveryDate2__", Sys.Helpers.Date.ISOSTringToDate(bulkReceiptData.DeliveryDate));
            }
            const indexByCompositeKey = {};
            items.forEach(it => {
                if (it.lineItemNumber && it.orderNumber) {
                    indexByCompositeKey[`${it.lineItemNumber}###${it.orderNumber}`] = it;
                }
            });
            // fill items
            await Lib.Purchasing.BR.Items.bulkReceiptItemsManager.Init(items.map(i => i.itemRuid));
            // trigger updates
            Sys.Helpers.Data.ForEachTableItem("LineItems__", (formItem) => {
                // build composite key
                const compositeKey = `${formItem.GetValue("POLineNumber__")}###${formItem.GetValue("OrderNumber__")}`;
                let incoming = indexByCompositeKey[compositeKey];
                if (!incoming) {
                    throw new Error(`No matching incoming item for form item with composite key ${compositeKey}`);
                }
                // apply received quantity or amount
                const isAmountBased = Lib.Purchasing.Items.IsAmountBasedItem(formItem);
                if (isAmountBased) {
                    // quantity is an amount when amount-based
                    formItem.SetValue("NetAmount__", incoming.quantity);
                    Lib.Purchasing.Receiving.OnChangeNetAmount(formItem);
                }
                else {
                    formItem.SetValue("ReceivedQuantity__", incoming.quantity);
                    Lib.Purchasing.Receiving.OnChangeReceivedQuantity(formItem);
                }
                // last delivery flag
                if (incoming.lastDelivery === true) {
                    formItem.SetValue("DeliveryCompleted__", true);
                    Lib.Purchasing.Receiving.OnChangeDeliveryCompleted(formItem);
                }
            });
            // check residual errors
            Lib.Purchasing.Receiving.CheckErrorOnTable();
            Lib.Purchasing.Receiving.CheckConfirmDelivery();
            return true;
        }
    }
    if (typeof _ENV_TEST_ENABLED === "undefined") {
        const main = new Main();
        Lib.P2P.HandleScriptError(main.Start());
    }
})(ExtractionScript || (ExtractionScript = {}));
//# sourceMappingURL=extractionscript.js.map

ui.CustomScript:
/* Bulk Receipt HTML page script */
/* eslint-disable dot-notation */
// eslint-disable-next-line @typescript-eslint/no-unused-vars
var CustomScript;
(function (CustomScript) {
    // List of BR status : "Draft" | "Canceled" | "Success" | "Partial success" | "Error";
    class Main {
        constructor(panes = ["GeneralInformation", "DocumentsPanel", "LineItems"], buttons = ["Approve", "Quit"], globalLayout = new Lib.P2P.Layout.Manager(panes, buttons), startInPopup = ProcessInstance.isOpenInPopup, selectedRuidEx = ProcessInstance.selectedRuidFromView, popupDialog = Lib.Purchasing.BR.CreatePopupDialog(), topMessageWarning = Lib.P2P.TopMessageWarning(Controls.TopPaneWarning, Controls.TopMessageWarning__), bulkActionsManager = null, bulkReceiptItemsManager = Lib.Purchasing.BR.Items.bulkReceiptItemsManager) {
            this.panes = panes;
            this.buttons = buttons;
            this.globalLayout = globalLayout;
            this.startInPopup = startInPopup;
            this.selectedRuidEx = selectedRuidEx;
            this.popupDialog = popupDialog;
            this.topMessageWarning = topMessageWarning;
            this.bulkActionsManager = bulkActionsManager;
            this.bulkReceiptItemsManager = bulkReceiptItemsManager;
            this.bulkActionsManager = new Lib.P2P.BulkActions.Manager(Controls.LineItems__, [
                {
                    actionParameters: {
                        controlName: "FillDeliveredQuantities__",
                        options: {
                            buttonLabel: "_FillDeliveredQuantities",
                            isOutline: true,
                            isRounded: true,
                            url: "",
                            style: 1
                        }
                    },
                    onClick: () => this.bulkReceiptItemsManager.FillDeliveredQuantities()
                },
                {
                    actionParameters: {
                        controlName: "ResetDeliveredQuantities__",
                        options: {
                            buttonLabel: "_ResetDeliveredQuantities",
                            isOutline: true,
                            isRounded: true,
                            style: 1
                        }
                    },
                    onClick: this.bulkReceiptItemsManager.ResetDeliveredQuantities
                }
            ]);
        }
        InitControls() {
            const banner = Sys.Helpers.Banner;
            banner.SetStatusCombo(Controls.BRStatus__);
            banner.SetHTMLBanner(Controls.HTMLBanner__);
            banner.SetMainTitle("BulkReceipt");
            banner.SetSubTitle();
            // former field DeliveryDate__ doesn't exist anymore - always hide
            if (Controls["DeliveryDate__"]) {
                Controls["DeliveryDate__"].Hide(true);
                Controls["DeliveryDate__"].SetRequired(false);
                Controls["DeliveryDate__"].SetReadOnly(true);
            }
            Controls.LineItems__.SetWidth("100%");
            Controls.LineItems__.SetExtendableColumn("Description__");
            Controls.Approve.OnClick = () => {
                if (Process.ShowFirstError() === null) {
                    ProcessInstance.ApproveAsynchronous("Approve");
                }
            };
            if (!ProcessInstance.state) {
                this.bulkActionsManager.InitBulkActions();
            }
            Lib.Purchasing.Receiving.InitControlsOnChange();
        }
        Start() {
            Sys.Helpers.EnableSmartSilentChange();
            ProcessInstance.SetSilentChange(true);
            this.globalLayout.ShowWaitScreen();
            if (!ProcessInstance.state) {
                Lib.Purchasing.BR.InitData();
            }
            if (this.startInPopup) {
                Sys.Helpers.Object.ForEach(Controls, function (control) {
                    const type = control.GetType();
                    if (type.startsWith("Panel")) {
                        control.Hide(true);
                    }
                });
            }
            else // We don't need this for popup
             {
                this.InitControls();
                if (this.selectedRuidEx && this.selectedRuidEx.length > 100) {
                    Popup.Alert(Language.Translate("_More than 100 items is selected, {0} removed", false, this.selectedRuidEx.length - 100), false, null, "_More than 100 items is selected title");
                }
            }
            // Autofill item quantities/amounts if popup
            if (this.startInPopup) {
                Lib.Purchasing.autoReceiveOrderData = {};
            }
            const promiseLayoutLoadAndStart = Lib.Purchasing.BR.Items.bulkReceiptItemsManager.Init()
                .Then(() => {
                const otherRecipients = Lib.Purchasing.Receiving.GetOtherRecipients();
                if (this.startInPopup) {
                    if (this.selectedRuidEx && this.selectedRuidEx.length > 100) {
                        Popup.Alert("_More than 100 items is selected Reject", false, () => ProcessInstance.Quit("quit"), "_More than 100 items is selected Reject title");
                    }
                    else if (otherRecipients.length > 0) {
                        Popup.Confirm("_You are about to receive items from other recipients message", false, () => {
                            this.popupDialog.Show();
                        }, () => ProcessInstance.Quit("quit"), "_You are about to receive items from other recipients title");
                    }
                    else {
                        this.popupDialog.Show();
                    }
                }
                else {
                    Lib.Purchasing.BR.InitWarnings(otherRecipients, this.topMessageWarning);
                    Lib.Purchasing.BR.FormTemplate.SetupFormTemplateManager();
                    this.bulkReceiptItemsManager.InitEvent();
                    this.bulkReceiptItemsManager.InitDisplayAsLinkColumns();
                    if (Controls.BRStatus__.GetValue() !== "Draft") {
                        return this.bulkReceiptItemsManager.FillRelatedGoodsReceipt();
                    }
                }
                return null;
            })
                .Catch(reason => {
                Lib.CommonDialog.NextAlert.Define("Bulk Receipt creation error", reason.message || reason, {
                    isError: true,
                    behaviorName: "InitError"
                });
            })
                .Finally(() => {
                this.globalLayout.HideWaitScreen();
                ProcessInstance.SetSilentChange(false);
            });
            return Sys.Helpers.Synchronizer.OnProgressFromPromise(promiseLayoutLoadAndStart, { progressDelay: 15000 });
        }
    }
    CustomScript.Main = Main;
    if (typeof _ENV_TEST_ENABLED === "undefined") {
        const main = new Main();
        main.Start();
    }
})(CustomScript || (CustomScript = {}));
//# sourceMappingURL=customscript.js.map

